Action.Str:
// Copy output/hong-kong-boarding-pass.png to /sdcard/Tasker/ first.
// The card fills the widget width, leaving an 8 dp margin on each side.
// Scale controls card height and live text size independently of width.
var widget_layout = (function () {
    var scale = 1;
    var hongKongNow = new Date(Date.now() + 8 * 60 * 60 * 1000);
    var today = Date.UTC(hongKongNow.getUTCFullYear(), hongKongNow.getUTCMonth(), hongKongNow.getUTCDate());
    var days = Math.round((Date.UTC(2026, 10, 22) - today) / 86400000);
    var number = days > 0 ? String(days) : days === 0 ? "TODAY" : "✈";
    var caption = days > 1 ? "DAYS TO GO" : days === 1 ? "DAY TO GO" : days === 0 ? "LET'S GO" : "ARRIVED";
    function text(value, size, color) {
        return { type: "Text", text: value, textSize: size * scale, color: color,
            bold: true, maxLines: 1, align: "Center", fontFamily: "SansSerif" };
    }
    return JSON.stringify({
        type: "Box", fillMaxSize: true, useMaterialYouColors: false,
        paddingStart: 8, paddingEnd: 8,
        horizontalAlignment: "Center", verticalAlignment: "Center", task: "Hong Kong Countdown",
        children: [{
            type: "Box", fillMaxWidth: true, height: 190 * scale,
            children: [
                { type: "Image", url: "file:///storage/emulated/0/Tasker/hong-kong-boarding-pass.png",
                    fillMaxSize: true, contentScale: "FillBounds" },
                { type: "Column", fillMaxSize: true, horizontalAlignment: "Center", children: [
                    { type: "Spacer", height: 66 * scale },
                    { type: "Box", fillMaxWidth: true, height: 48 * scale,
                        horizontalAlignment: "Center", verticalAlignment: "Center",
                        children: [text(number, days > 0 ? (days >= 100 ? 34 : 42) : 20, "#FFC47B")] },
                    { type: "Box", fillMaxWidth: true, height: 13 * scale,
                        horizontalAlignment: "Center", verticalAlignment: "Center",
                        children: [text(caption, 7, "#FFFFFF")] }
                ] }
            ]
        }]
    });
})();
